input.command:
mkdir -p /tmp/rt && cat > /tmp/rt/run.sh <<'SH'
#!/bin/bash
E=/workspace/dataset/test3_executable
run() {
  o=$("$E" "$@" 2>/tmp/rt/e); c=$?; e=$(cat /tmp/rt/e)
  printf 'ARGS='; for a in "$@"; do printf '[%s]' "$a"; done
  printf '\n  exit=%d\n  OUT=%q\n  ERR=%q\n' "$c" "$o" "$e"
}
SH
chmod +x /tmp/rt/run.sh; echo ok
